function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.sin(t), H - 50 - 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H - 50 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 20 * Math.cos(t), H - 30 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 10 * Math.cos(t), H - 10 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H - 50 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) - 20 * Math.cos(t), H - 30 - 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50 * Math.sin(t) - 10 * Math.cos(t), H - 10 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t) + 10 * Math.cos(t), H - 10 - 20 * Math.sin(t));
  ctx.quadraticCurveTo(W/2 + 50 * Math.sin(t), H - 20 - 20 * Math.sin(t), W/2 + 50 * Math.sin(t) - 10 * Math.cos(t), H - 10 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.restore();
}
